using UnityEngine;

public class BoardManager : MonoBehaviour
{
    public GameObject[] jewels; // Array de sprites de joyas
    public int boardWidth; // Ancho del tablero
    public int boardHeight; // Alto del tablero

    private GameObject[,] board; // Tablero de joyas
    private int jewelsCount; // Contador de joyas en el tablero

    void Start()
    {
        // Generar el tablero
        board = new GameObject[boardWidth, boardHeight];
        for (int i = 0; i < boardWidth; i++)
        {
            for (int j = 0; j < boardHeight; j++)
            {
                int jewelIndex = Random.Range(0, jewels.Length);
                board[i, j] = Instantiate(jewels[jewelIndex], new Vector3(i, j, 0), Quaternion.identity);
            }
        }
        jewelsCount = 0; // Inicializar el contador de joyas
    }

    void Update()
    {
        // Comprobar si se ha producido un match
        CheckForMatches();
    }

    void CheckForMatches()
    {
        // Seleccionar todas las joyas en el tablero
        ListView jewelList = new ListView();
        for (int i = 0; i < boardWidth; i++)
        {
            for (int j = 0; j < boardHeight; j++)
            {
                jewelList.Add(board[i, j]);
            }
        }

        // Buscar matches
        List<Tuple<int, int>> matches = new List<Tuple<int, int>>();
        foreach (GameObject jewel in jewelList)
        {
            // Comprobar si la joya seleccionada tiene un compañero de idéntico tipo y orientación
            for (int dx = -1; dx <= 1; dx++)
            {
                for (int dy = -1; dy <= 1; dy++)
                {
                    if (dx == 0 && dy == 0) continue;

                    int newX = jewel.transform.position.x + dx;
                    int newY = jewel.transform.position.y + dy;

                    if (newX >= 0 && newX < boardWidth && newY >= 0 && newY < boardHeight)
                    {
                        GameObject neighbor = board[newX, newY];
                        if (neighbor != null && jewel.GetComponent< Jewel>().type == neighbor.GetComponent<Jewel>().type)
                        {
                            matches.Add(new Tuple<int, int>(newX, newY));
                        }
                    }
                }
            }
        }

        // Eliminar los matches
        foreach (Tuple<int, int> match in matches)
        {
            board[match.Item1, match.Item2] = null;
            jewelsCount--;
        }
    }
}
```
